[CmdletBinding()]param([Parameter(Mandatory=$true)][string]$Path)
$ErrorActionPreference='Stop';$d=[IO.Path]::GetFullPath($Path);$x=Get-Content (Join-Path $d 'project-story.json') -Raw|ConvertFrom-Json;if($x.offer.actual_hours -gt $x.offer.planned_hours -or $x.offer.actual_cost -gt $x.offer.planned_cost){throw 'STORY_BUDGET_MISMATCH'};$ids=@();foreach($p in @($x.pages)){if(-not(Test-Path (Join-Path $d $p.sourcePath) -PathType Leaf)){throw 'STORY_PAGE_SOURCE_MISSING'};if((Get-Content (Join-Path $d $p.sourcePath) -Raw).Trim().Length -eq 0){throw 'STORY_PAGE_EMPTY'};$ids+=$p.id};foreach($t in @($x.tickets)){if(@($t.acceptance).Count -eq 0 -or @($t.evidence).Count -eq 0 -or @($t.comments|? type -eq 'closing').Count -ne 1 -or @($t.comments|? type -eq 'working').Count -lt 1){throw 'STORY_TICKET_CLOSURE_INVALID'};if(@($t.worklogs|? hours -le 0).Count -gt 0){throw 'STORY_WORKLOG_INVALID'}};for($i=1;$i -lt @($x.timeline).Count;$i++){if([datetime]$x.timeline[$i].time -lt [datetime]$x.timeline[$i-1].time){throw 'STORY_TIMELINE_ORDER_INVALID'}};if(@($x.hypercare).Count -lt 3 -or @($x.hypercare|? status -ne 'closed').Count -gt 0 -or @($x.hypercare|? priority -eq 'P1').Count -gt 0){throw 'STORY_HYPERCARE_EXIT_INVALID'};foreach($e in @($x.graph)){if([string]$e.from -eq '' -or [string]$e.to -eq ''){throw 'STORY_GRAPH_REFERENCE_INVALID'}};Write-Host 'PASS: Hardened project story validates pages, tickets, worklogs, timeline, hypercare and graph.'
